entries[19790] = { ["name"] = "Thoriumgranate", ["text"] = "Wirken in 3 sek.\nTools:\nSchmiedehammer\nReagenzien:\nThoriumapparat , Thoriumbarren (3), Dichtes Sprengpulver (3), Runenstoff (3)\n(3)\nBenötigt Ingenieurskunst\n(260)" }
