entries[19792] = { ["name"] = "Thoriumgewehr", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr (2), Mithrilgehäuse (2), Thoriumapparat (2), Thoriumbarren (4), Tödliches Zielfernrohr\nThoriumgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n55 - 102 Schaden Tempo 2.50\n(31.40 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\n47\nAnlegen: Erhöht die Distanzangriffskraft um 17." }
entries[19793] = { ["name"] = "Lebensechte mechanische Kröte", ["text"] = "Wirken in 3 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nEssenz des Lebens , Thoriumapparat (4), Goldkraftkern , Unverwüstliches Leder\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Eure lebensechte mechanische Kröte beschwören und freigeben." }
entries[19794] = { ["name"] = "Zaubermachtschutzbrille Xtrem-Plus", ["text"] = "Wirken in 45 sek.\nTools:\nBogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nZaubermachtschutzbrille Xtrem , Sternrubin (4), Verzaubertes Leder (2), Runenstoff (8)\nZaubermachtschutzbrille Xtrem-Plus\nWird beim Anlegen gebunden\nKopf Stoff\n57 Rüstung\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst\n(270)\nAnlegen: Erhöht die Zaubermacht um 27." }
entries[19795] = { ["name"] = "Thoriumröhre", ["text"] = "Wirken in 3 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nThoriumbarren (6)" }
entries[19796] = { ["name"] = "Dunkeleisengewehr", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nThoriumröhre (2), Dunkeleisenbarren (6), Tödliches Zielfernrohr (2), Blauer Saphir (2), Großer Opal (2), Unverwüstliches Leder (4)\nDunkeleisengewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n68 - 127 Schaden Tempo 2.70\n(36.11 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\n50\nAnlegen: Gewährt eine Chance, Euer Distanzziel mit einem Schattenschuss zu treffen und 18 to 26 Schattenschaden zu verursachen." }
