entries[20184] = { ["name"] = "Richturteil der Gerechtigkeit", ["text"] = "100 Meter Reichweite\nSofort\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 20 sec lang und hindert ihn an der Flucht. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
entries[20185] = { ["name"] = "Richturteil des Lichts", ["text"] = "100 Meter Reichweite\nSofort\nErfüllt den Paladin 30 min lang mit göttlichem Licht, das jedem Nahkampfangriff eine Chance verleiht, den Paladin um 0 zu heilen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 20 sec lang und verleiht Angriffen und Zaubern, die gegen den gerichteten Feind ausgeführt werden, eine Chance den Angreifer um 2% seiner maximalen Gesundheit zu heilen. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
